worksheets.solution_code:
def ucln(a, b):
    while b != 0:
        r = a % b
        a = b
        b = r
    return a

def bcnn(a, b):
    return a * b // ucln(a, b)

x = int(input())
y = int(input())
print("UCLN:", ucln(x, y))
print("BCNN:", bcnn(x, y))

