def la_so(x):
    bat_dau = 0
    if x[0] == "-":
        bat_dau = 1
        if len(x) == 1:
            return False
    for i in range(bat_dau, len(x)):
        if x[i] not in "0123456789":
            return False
    return True

A = input().split()
tong = 0
dem = 0
for x in A:
    if la_so(x):
        tong = tong + int(x)
        dem = dem + 1
if dem == 0:
    print("Không có số hợp lệ")
else:
    print("Số hợp lệ:", dem)
    print("Trung bình:", tong / dem)
